int create_virtio_gpu_object(struct virtio_gpu_device *vgdev, unsigned long size, bool kernel, bool pinned, struct virtio_gpu_object **bo_ptr) {
    struct virtio_gpu_object *bo = NULL;
    size_t obj_size = sizeof(struct virtio_gpu_object);
    int ret = -ENOMEM;

    if (!vgdev || !bo_ptr) {
        return -EINVAL;
    }

    bo = (struct virtio_gpu_object *)malloc(obj_size);
    if (!bo) {
        return -ENOMEM;
    }

    if (kernel) {
        bo->type = VIRTIO_GPU_OBJECT_KERNEL;
    } else {
        bo->type = VIRTIO_GPU_OBJECT_USER;
    }

    bo->size = size;
    bo->pinned = pinned;

    if (pinned) {
        ret = pin_memory(vgdev, bo);
        if (ret < 0) {
            goto error;
        }
    }

    *bo_ptr = bo;
    return 0;

error:
    free(bo);
    *bo_ptr = NULL;
    return ret;
}
